import { z } from 'zod';
import type { ProfileCandidate } from '../../types/design-profile';

export const selectionSchema = {
  type: 'object',
  properties: {
    selected: {
      type: 'array',
      maxItems: 3,
      items: {
        type: 'object',
        properties: { id: { type: 'string' }, reason: { type: 'string' } },
        required: ['id', 'reason'],
        additionalProperties: false,
      },
    },
  },
  required: ['selected'],
  additionalProperties: false,
};
const selected = z
  .object({
    selected: z
      .array(
        z
          .object({ id: z.string(), reason: z.string().trim().min(1).max(500) })
          .strict(),
      )
      .max(3),
  })
  .strict();

export const selectProfileReferences = (
  input: unknown,
  candidates: ProfileCandidate[],
): Array<ProfileCandidate & { reason: string }> => {
  const value = selected.parse(input);
  const ids = new Set<string>();
  return value.selected.map(({ id, reason }) => {
    const candidate = candidates.find((item) => item.reference.id === id);
    if (!candidate || ids.has(id))
      throw new Error(
        'Profile selection contains an unknown or duplicate reference',
      );
    ids.add(id);
    return { ...candidate, reason };
  });
};
